        if self.args.no_mv:
            raise Pebkac(403, "the rename/move feature is disabled in server config")
        x = self.conn.hsrv.broker.ask("up2k.handle_mv", self.uname, vsrc, vdst)
        self.loud_reply(x.get(), status=201)
