                        key=tag['key'].replace(' ', '_'),
                        value=tag['value'].replace(' ', '_')
                    )
                    if tag_name not in acache[asset['id']]['tags']:
                        acache[asset['id']]['tags'].append(tag_name)
                    if tag['key'] in trans_list:
                        acache[asset['id']][tag['key']] = tag['value']
