class GlancesActions(object):
    def __init__(self, args=None):
        """Init GlancesActions class."""
        self.status = {}
        if hasattr(args, 'time'):
            self.start_timer = Timer(args.time * 2)
        else:
            self.start_timer = Timer(3)
    def get(self, stat_name):
        """Get the stat_name criticity."""
        try:
            return self.status[stat_name]
        except KeyError:
            return None
    def set(self, stat_name, criticity):
        """Set the stat_name to criticity."""
        self.status[stat_name] = criticity
    def run(self, stat_name, criticity, commands, repeat, mustache_dict=None):
        """Run the commands (in background).
        - stats_name: plugin_name (+ header)
        - criticity: criticity of the trigger
        - commands: a list of command line with optional {{mustache}}
        - If True, then repeat the action
        - mustache_dict: Plugin stats (can be use within {{mustache}})
        Return True if the commands have been ran.
        """
        if (self.get(stat_name) == criticity and not repeat) or \
           not self.start_timer.finished():
            return False
        logger.debug("{} action {} for {} ({}) with stats {}".format(
            "Repeat" if repeat else "Run",
            commands, stat_name, criticity, mustache_dict))
        for cmd in commands:
            if chevron_tag:
                cmd_full = chevron.render(cmd, mustache_dict)
            else:
                cmd_full = cmd
            logger.info("Action triggered for {} ({}): {}".format(stat_name,
                                                                  criticity,
                                                                  cmd_full))
            try:
                ret = secure_popen(cmd_full)
            except OSError as e:
                logger.error("Action error for {} ({}): {}".format(stat_name,
                                                                   criticity,
                                                                   e))
            else:
                logger.debug("Action result for {} ({}): {}".format(stat_name,
                                                                    criticity,
                                                                    ret))
        self.set(stat_name, criticity)
        return True
def secure_popen(cmd):
    """A more or less secure way to execute system command
    Return: the result of the command OR an error message
    """
    ret = None
    cmd_split_redirect = cmd.split('>')
    if len(cmd_split_redirect) > 2:
        return 'Glances error: Only one file redirection allowed ({})'.format(cmd)
    elif len(cmd_split_redirect) == 2:
        stdout_redirect = cmd_split_redirect[1].strip()
        cmd = cmd_split_redirect[0]
    else:
        stdout_redirect = None
    sub_cmd_stdin = None
    p_last = None
    for sub_cmd in cmd.split('|'):
        sub_cmd_split = [i for i in sub_cmd.split(' ') if i]
        p = Popen(sub_cmd_split,
                  shell=False,
                  stdin=sub_cmd_stdin,
                  stdout=PIPE,
                  stderr=PIPE)
        if p_last is not None:
            p_last.stdout.close()
        p_last = p
        sub_cmd_stdin = p.stdout
    p_ret = p_last.communicate()
    if nativestr(p_ret[1]) == '':
        ret = nativestr(p_ret[0])
        if stdout_redirect is not None:
            with open(stdout_redirect, "w") as stdout_redirect_file:
                stdout_redirect_file.write(ret)
    else:
        ret = nativestr(p_ret[1])
    return ret
class GlancesPlugin(object):
    def __init__(self,
                 args=None,
                 config=None,
                 items_history_list=None,
                 stats_init_value={}):
        """Init the plugin of plugins class.
        All Glances' plugins should inherit from this class. Most of the
        methods are already implemented in the father classes.
        Your plugin should return a dict or a list of dicts (stored in the
        self.stats). As an example, you can have a look on the mem plugin
        (for dict) or network (for list of dicts).
        A plugin should implement:
        - the __init__ constructor: define the self.display_curse
        - the reset method: to set your self.stats variable to {} or []
        - the update method: where your self.stats variable is set
        and optionnaly:
        - the get_key method: set the key of the dict (only for list of dict)
        - the update_view method: only if you need to trick your output
        - the msg_curse: define the curse (UI) message (if display_curse is True)
        :args: args parameters
        :items_history_list: list of items to store in the history
        :stats_init_value: Default value for a stats item
        """
        pos = self.__class__.__module__.find('glances_') + len('glances') + 1
        self.plugin_name = self.__class__.__module__[pos:]
        self.args = args
        self._align = 'left'
        self._input_method = 'local'
        self._short_system_name = None
        self.items_history_list = items_history_list
        self.stats_history = self.init_stats_history()
        self._limits = dict()
        if config is not None:
            logger.debug('Load section {} in {}'.format(self.plugin_name,
                                                        config.config_file_paths()))
            self.load_limits(config=config)
        self.actions = GlancesActions(args=args)
        self.views = dict()
        self.hide_zero = False
        self.hide_zero_fields = []
        self.stats_init_value = stats_init_value
        self.stats = None
        self.reset()
    def __repr__(self):
        """Return the raw stats."""
        return self.stats
    def __str__(self):
        """Return the human-readable stats."""
        return str(self.stats)
    def get_init_value(self):
        """Return a copy of the init value."""
        return copy.copy(self.stats_init_value)
    def reset(self):
        """Reset the stats.
        This method should be overwrited by childs' classes.
        """
        self.stats = self.get_init_value()
    def exit(self):
        """Just log an event when Glances exit."""
        logger.debug("Stop the {} plugin".format(self.plugin_name))
    def get_key(self):
        """Return the key of the list."""
        return None
    def is_enable(self, plugin_name=None):
        """Return true if plugin is enabled."""
        if not plugin_name:
            plugin_name = self.plugin_name
        try:
            d = getattr(self.args, 'disable_' + plugin_name)
        except AttributeError:
            return True
        else:
            return d is False
    def is_disable(self, plugin_name=None):
        """Return true if plugin is disabled."""
        return not self.is_enable(plugin_name=plugin_name)
    def _json_dumps(self, d):
        """Return the object 'd' in a JSON format.
        Manage the issue
        """
        try:
            return json.dumps(d)
        except UnicodeDecodeError:
            return json.dumps(d, ensure_ascii=False)
    def history_enable(self):
        return self.args is not None and not self.args.disable_history and self.get_items_history_list() is not None
    def init_stats_history(self):
        """Init the stats history (dict of GlancesAttribute)."""
        if self.history_enable():
            init_list = [a['name'] for a in self.get_items_history_list()]
            logger.debug("Stats history activated for plugin {} (items: {})".format(self.plugin_name, init_list))
        return GlancesHistory()
    def reset_stats_history(self):
        """Reset the stats history (dict of GlancesAttribute)."""
        if self.history_enable():
            reset_list = [a['name'] for a in self.get_items_history_list()]
            logger.debug("Reset history for plugin {} (items: {})".format(self.plugin_name, reset_list))
            self.stats_history.reset()
    def update_stats_history(self):
        """Update stats history."""
        if self.get_key() is None:
            item_name = ''
        else:
            item_name = self.get_key()
        if self.get_export() and self.history_enable():
            for i in self.get_items_history_list():
                if isinstance(self.get_export(), list):
                    for l in self.get_export():
                        self.stats_history.add(
                            nativestr(l[item_name]) + '_' + nativestr(i['name']),
                            l[i['name']],
                            description=i['description'],
                            history_max_size=self._limits['history_size'])
                else:
                    self.stats_history.add(nativestr(i['name']),
                                           self.get_export()[i['name']],
                                           description=i['description'],
                                           history_max_size=self._limits['history_size'])
    def get_items_history_list(self):
        """Return the items history list."""
        return self.items_history_list
    def get_raw_history(self, item=None, nb=0):
        """Return the history (RAW format).
        - the stats history (dict of list) if item is None
        - the stats history for the given item (list) instead
        - None if item did not exist in the history
        """
        s = self.stats_history.get(nb=nb)
        if item is None:
            return s
        else:
            if item in s:
                return s[item]
            else:
                return None
    def get_json_history(self, item=None, nb=0):
        """Return the history (JSON format).
        - the stats history (dict of list) if item is None
        - the stats history for the given item (list) instead
        - None if item did not exist in the history
        Limit to lasts nb items (all if nb=0)
        """
        s = self.stats_history.get_json(nb=nb)
        if item is None:
            return s
        else:
            if item in s:
                return s[item]
            else:
                return None
    def get_export_history(self, item=None):
