        stream = self.h2_conn.streams.get(stream_id, None)
        if (
            stream is not None
            and
            stream.state_machine.state is not h2.stream.StreamState.CLOSED
            and
            self.h2_conn.state_machine.state is not h2.connection.ConnectionState.CLOSED
