        result.update(**self._repository_response())
        return jsonify(**result)
    def _is_archive(self, path):
        _, ext = os.path.splitext(path)
        if ext in PluginManagerPlugin.ARCHIVE_EXTENSIONS:
            return True
        kind = filetype.guess(path)
