            return f".{kind.extension}" in PluginManagerPlugin.ARCHIVE_EXTENSIONS
        return False
    def _is_pythonfile(self, path):
        _, ext = os.path.splitext(path)
        if ext in PluginManagerPlugin.PYTHON_EXTENSIONS:
            import ast
            try:
